                    <span class="tag">${product.tag}</span>
                  </div>
                  <div class="stack">
                    <a class="product-link" href="${product.href}">
                      <h3 class="product-title">${product.name}</h3>
                    </a>
                    <p class="copy">${product.note}</p>
                  </div>
