              <h2 id="deals-heading">Deals</h2>
              <p>Limited-time offers and member perks that make the right buy easier to justify.</p>
            </div>
          </div>
          <div class="promo-list">
            ${items.map((deal, index) => `
              <article class="promo-card ${index === 0 ? 'featured' : ''}">
                <div class="stack">
                  <span class="deal-badge">${deal.badge}</span>
                  <h3 class="deal-title">${deal.title}</h3>
                  <p class="copy">${deal.copy}</p>
                </div>
                <a class="button" href="#featured">${deal.cta}</a>
              </article>
            `).join('')}
          </div>
        </section>
      `;
    }

    function editorialSection(items) {
      return `
        <section id="editorial" aria-labelledby="editorial-heading">
          <div class="section-head">
            <div>
              <h2 id="editorial-heading">Editorial content</h2>
              <p>Ideas, maker notes, and style guidance to turn browsing into a better shopping session.</p>
            </div>
