                  <span class="kicker">${item.category}</span>
                  <h3 class="editorial-title">${item.title}</h3>
                  <p class="copy">${item.copy}</p>
                </div>
                <footer>
                  <time datetime="2026-${item.date === 'Apr 18' ? '04-18' : item.date === 'Apr 11' ? '04-11' : '03-29'}">${item.date}</time>
                  <a class="ghost-button" href="#featured">Read more</a>
                </footer>
              </article>
            `).join('')}
          </div>
        </section>
      `;
    }

    function app() {
      return shell(`
        ${hero()}
        ${featuredSection(featuredProducts)}
        ${dealsSection(deals)}
        ${editorialSection(editorials)}
      `);
    }

    function announce(message) {
      statusText.textContent = message;
    }

    root.innerHTML = app();
    document.body.appendChild(statusText);

    document.addEventListener('click', (event) => {
      const trigger = event.target.closest('[data-add-to-bag]');
      if (!trigger) {
        return;
      }

      announce(`${trigger.getAttribute('data-add-to-bag')} added to bag.`);
    });
