                  <span class="deal-badge">${deal.badge}</span>
                  <h3 class="deal-title">${deal.title}</h3>
                  <p class="copy">${deal.copy}</p>
                </div>
                <a class="button" href="#featured">${deal.cta}</a>
              </article>
            `).join('')}
          </div>
        </section>
      `;
    }

    function editorialSection(items) {
      return `
        <section id="editorial" aria-labelledby="editorial-heading">
          <div class="section-head">
            <div>
              <h2 id="editorial-heading">Editorial content</h2>
