                </footer>
              </article>
            `).join('')}
          </div>
        </section>
      `;
    }

    function app() {
      return shell(`
        ${hero()}
        ${featuredSection(featuredProducts)}
        ${dealsSection(deals)}
        ${editorialSection(editorials)}
      `);
    }

    function announce(message) {
      statusText.textContent = message;
    }

    root.innerHTML = app();
    document.body.appendChild(statusText);

    document.addEventListener('click', (event) => {
      const trigger = event.target.closest('[data-add-to-bag]');
      if (!trigger) {
